 function updatePostStatus(title:string,status:string){setContentPosts(old=>old.map(post=>post.title===title?{...post,status}:post));if(selectedPost?.title===title)setSelectedPost({...selectedPost,status});setPostActivity(old=>({...old,[title]:[{action:`Status changed to ${status}`,by:role,time:new Date().toLocaleString("en-IE",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"})},...(old[title]??[])]}));ping(`${title} · ${status.toLowerCase()}`)}
 function openPost(post:SocialPost){setPostBackArea(area==="Review"?"Review":"Project");const project=projects.find(item=>item.name===post.project);if(project){setSelectedId(project.id);setProjectTab("Content")}setSelectedPost(post);setIsBriefDetail(false);setCommentDraft("");setArea("Post")}
 function startNewPost(projectId=selectedProject.id,title="",destination="Review"){setNewPostDraft(old=>({...old,projectId,platform:"LinkedIn",format:"Single image",title,caption:"",date:"Oct 20",destination,reviewer:"María",media:""}));setShowNewPost(true)}
 function downloadInvoiceDraft(project:Project){const cleanName=project.name.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");const amount=(project.fee??0).toLocaleString("en-US",{style:"currency",currency:"USD"});const html=`<!doctype html><html><head><meta charset="utf-8"><title>Invoice draft · ${cleanName}</title><style>body{font:16px Arial,sans-serif;color:#222;margin:56px;max-width:760px}header{border-bottom:4px solid #1557b8;padding-bottom:24px}h1{font-size:36px;margin:0}small{color:#666}.row{display:flex;justify-content:space-between;border-bottom:1px solid #ddd;padding:18px 0}.total{font-size:26px;font-weight:bold}.note{margin-top:48px;padding:16px;background:#fff4c6}</style></head><body><header><small>AGENCY OS · INVOICE DRAFT</small><h1>Invoice</h1></header><p><b>Bill to:</b> ${cleanName}<br><b>Invoice date:</b> ${new Date().toLocaleDateString("en-IE")}<br><b>Invoice number:</b> Add invoice number</p><div class="row"><span>Agency services · monthly</span><b>${amount}</b></div><div class="row total"><span>Total due (USD)</span><span>${amount}</span></div><div class="note"><b>Draft:</b> Add the agency legal name, client billing details, payment terms, Revolut details, and applicable tax before sending. This draft contains the client fee only.</div></body></html>`;const blob=new Blob([html],{type:"text/html"});const url=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=url;anchor.download=`invoice-draft-${project.id}.html`;anchor.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000);ping("Client-only invoice draft downloaded")}
