 const nav=[{area:"Home",label:isFreelancer?"My day":"Today",group:"RUN TODAY",icon:BriefcaseBusiness},{area:"Review",label:isFreelancer?"Feedback":"Inbox",group:"RUN TODAY",icon:CheckCircle2},{area:"Calendar",label:"Schedule",group:"RUN TODAY",icon:CalendarDays},{area:"Projects",label:isFreelancer?"My clients":"All clients",group:"CLIENTS",icon:FolderKanban},{area:"Team",label:"Team",group:"AGENCY",icon:Users},{area:"Operations",label:"Playbook",group:"AGENCY",icon:Workflow},{area:"Financials",label:"Finance",group:"AGENCY",icon:CircleDollarSign}];
